SET NAMES utf8mb4;

-- STEP 0. Backup of the table as it is now (once). To undo everything later:
--   DELETE FROM homepage_sections; INSERT INTO homepage_sections SELECT * FROM homepage_sections_bak_20261022;
CREATE TABLE IF NOT EXISTS homepage_sections_bak_20261022 LIKE homepage_sections;
INSERT INTO homepage_sections_bak_20261022 SELECT * FROM homepage_sections WHERE NOT EXISTS (SELECT 1 FROM homepage_sections_bak_20261022);
SELECT COUNT(*) AS rows_in_backup FROM homepage_sections_bak_20261022;

