-- STEP 2. Existing sections: add the new settings (lists, steps, toggles...) they do not have yet.
--         Values already saved are kept (JSON_MERGE_PATCH: the saved settings win).
UPDATE homepage_sections SET settings = JSON_MERGE_PATCH('{"title_after":"and get in.","rotating_words":["college","course","school","scholarship","exam"],"search_placeholder":"Try “MBA in Pune” or “NEET UG”","popular":[{"label":"Online MBA","url":"#online"},{"label":"B.Tech","url":"/search?q=B.Tech"},{"label":"MBA","url":"/search?q=MBA"},{"label":"Scholarships","url":"/scholarships-and-benefits"}],"popular_live_exam":true,"assurances":["Exam dates from official notices","Counselling is free","Compare before you apply"],"show_live":true}', COALESCE(NULLIF(settings, ''), '{}')), updated_at = NOW() WHERE section_key = 'hero_banner';
