UPDATE homepage_sections SET settings = JSON_MERGE_PATCH('{"pillars":[{"icon":"calendar","title":"Dates with sources","text":"Exam and counselling dates are taken from the official notices."},{"icon":"shield","title":"Compare in the open","text":"Fees, campuses and placements side by side, with the year each figure is from."},{"icon":"award","title":"DPIIT-recognised","text":"Admission counselling is free. You are never charged by Enrollzy for an admission."}],"show_reviews":true,"show_counts":true}', COALESCE(NULLIF(settings, ''), '{}')), updated_at = NOW() WHERE section_key = 'testimonials';
