-- STEP 4 (recommended). The design's order. Sections of the old design go after them (they are not shown).
--         You can change the order later in Admin > Homepage Sections (drag, then Save Order).
UPDATE homepage_sections SET sort_order = CASE section_key WHEN 'hero_banner' THEN 1 WHEN 'journey_stages' THEN 2 WHEN 'happening_now' THEN 3 WHEN 'university_grid' THEN 4 WHEN 'university_comparison' THEN 5 WHEN 'online_degrees' THEN 6 WHEN 'noteworthy_mentions' THEN 7 WHEN 'specialized_courses' THEN 8 WHEN 'institute_marquee' THEN 9 WHEN 'free_counselling' THEN 10 WHEN 'school_marquee' THEN 11 WHEN 'expert_carousel' THEN 12 WHEN 'testimonials' THEN 13 WHEN 'blogs' THEN 14 WHEN 'faq' THEN 15 ELSE IF(sort_order >= 100, sort_order, 100 + sort_order) END, updated_at = NOW();

-- CHECK: the homepage sections in order (on_homepage = 1 for the 15 sections of the design).
SELECT sort_order, section_key, name, is_visible, section_key IN ('hero_banner', 'journey_stages', 'happening_now', 'university_grid', 'university_comparison', 'online_degrees', 'noteworthy_mentions', 'specialized_courses', 'institute_marquee', 'free_counselling', 'school_marquee', 'expert_carousel', 'testimonials', 'blogs', 'faq') AS on_homepage, title FROM homepage_sections ORDER BY sort_order;
